#!/bin/bash
set -e

# Prints prescription frequency in plain language for patients (e.g.
# 'Twice a day (BD)' instead of just 'BD') on both print paths -- the
# OPD Case Sheet and the separate Visit Summary print. The doctor's
# on-screen entry (OD/BD/TDS/QID dropdown) is completely untouched --
# this only changes what gets printed, not what's stored or how it's
# entered.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/print-templates"
echo "" | base64 -d > "app/print-templates/actions.js"
echo "Wrote app/print-templates/actions.js"

mkdir -p "app/visit-summary-print/[encounterId]"
echo "" | base64 -d > "app/visit-summary-print/[encounterId]/page.js"
echo "Wrote app/visit-summary-print/[encounterId]/page.js"

git add "app/print-templates/actions.js" "app/visit-summary-print/[encounterId]/page.js"
git commit -m "Print prescription frequency in plain language for patients (both print paths)"
git push

echo "Done."
